#include <iostream>
#include <memory>
#include <utility>
struct Node {
    int value{};
    std::unique_ptr<Node> next;
    explicit Node(int n) : value(n) {}
};
void pushFront(std::unique_ptr<Node>& head, int value) {
    auto node = std::make_unique<Node>(value);
    node->next = std::move(head);
    head = std::move(node);
}
void clear(std::unique_ptr<Node>& head) {
    while (head) { auto next = std::move(head->next); head = std::move(next); }
}
int main() {
    std::unique_ptr<Node> head;
    for (int value : {1, 2, 3}) { pushFront(head, value); }
    for (Node* node = head.get(); node; node = node->next.get()) { std::cout << node->value << ' '; }
    std::cout << '\n';
    clear(head);
    std::cout << bool(head) << '\n';
}

