#include <iostream>
#include <memory>
#include <utility>
struct Node {
    int value{};
    std::unique_ptr<Node> next;
    explicit Node(int n) : value(n) {}
};
void pushFront(std::unique_ptr<Node>& head, int value) {
    auto node = std::make_unique<Node>(value);
    node->next = std::move(head);
    head = std::move(node);
}
void clear(std::unique_ptr<Node>& head) {
    while (head) { auto next = std::move(head->next); head = std::move(next); }
}
int main() {
    int n{};
    if (!(std::cin >> n) || n < 0 || n > 100) { std::cout << "invalid\n"; return 0; }
    std::unique_ptr<Node> head;
    for (int i = 0; i < n; ++i) {
        int value{};
        if (!(std::cin >> value) || value < -1000 || value > 1000) { clear(head); std::cout << "invalid\n"; return 0; }
        pushFront(head, value);
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) { clear(head); std::cout << "invalid\n"; return 0; }
    bool first{true};
    for (Node* node = head.get(); node; node = node->next.get()) {
        if (!first) { std::cout << ' '; }
        std::cout << node->value;
        first = false;
    }
    std::cout << '\n';
    clear(head);
    std::cout << "empty=" << (!head) << '\n';
}

