#include <iostream>
#include <fstream>
#include <memory>
#include <utility>
int live{};
struct Node {
    int value{};
    std::unique_ptr<Node> next;
    explicit Node(int v) : value(v) { ++live; }
    ~Node() { --live; }
};
void clear(std::unique_ptr<Node>& head) {
    while (head) { auto next = std::move(head->next); head = std::move(next); }
}
int main() {
    std::ifstream input{"input.txt"};
    if (!input) { std::cout << "missing\n"; return 0; }
    int n{};
    if (!(input >> n) || n < 0 || n > 10) { std::cout << "invalid\n"; return 0; }
    std::unique_ptr<Node> head;
    for (int i = 0; i < n; ++i) {
        int value{};
        if (!(input >> value) || value < -1000 || value > 1000) { clear(head); std::cout << "invalid\n"; return 0; }
        auto node = std::make_unique<Node>(value);
        node->next = std::move(head);
        head = std::move(node);
    }
    input >> std::ws;
    if (!input.eof()) { clear(head); std::cout << "invalid\n"; return 0; }
    std::ofstream output{"reversed.txt"};
    bool first{true};
    for (Node* node = head.get(); node; node = node->next.get()) {
        if (!first) { output << ' '; }
        output << node->value;
        first = false;
    }
    output << '\n';
    output.close();
    clear(head);
    if (!output) { std::cout << "write-error\n"; return 0; }
    std::cout << "exported live=" << live << '\n';
    return live == 0 ? 0 : 1;
}
